  const metrics=$('metrics');const existing=Object.fromEntries([...metrics.querySelectorAll('select')].map(x=>[x.name,x.value]));metrics.replaceChildren();const head=node('div',undefined,'metric metric-head');head.append(node('span',''),node('span','A'),node('span','B'));metrics.append(head);for(const key of ['identity','seams','naturalness','subjectSize','quality']){const row=node('div',undefined,'metric');row.append(node('span',t(key)));for(const label of ['A','B']){const select=node('select');select.name=key+label;select.setAttribute('aria-label',`${t(key)} ${label}`);for(let i=1;i<=5;i++){const opt=node('option',String(i));opt.value=String(i);select.append(opt);}select.value=r.locked?.scores[key+label]||existing[key+label]||'3';select.disabled=Boolean(r.locked);row.append(select);}metrics.append(row);}
