async function submitScore(event){event.preventDefault();if(!reviewState||reviewState.locked)return;const r=reviewState,score={schema:'bd.dualframe.comparison.v1',comparison_id:r.comparison_id,created_at:new Date().toISOString(),pair_id:r.pair.pair_id,original_sha256:r.pair.original.sha256,direction:opposite(r.pair.original.source_orientation),target_ratio:RATIOS[opposite(r.pair.original.source_orientation)],review_scale_policy:'equal-canvas-v1',randomization_seed:r.pair.comparison_seed,label_order:r.order,eligible:r.eligibility.eligible,classification:r.eligibility.classification,exclusion_reasons:r.eligibility.reasons,scores:Object.fromEntries(new FormData(event.target)),preference:$('preference').value,note:$('score-note').value,outputs:{web:publicManifest(r.web),reference:publicManifest(r.reference)},baseline:[$('baseline-mode').value],locked:true};await addScore(score);scores.push(score);r.locked=score;renderReview();scoreSummary();}
